131	      row[`${config.column}_pct`] = coalitionStats.coalitionPct;
132	      return;
133	    }
134	    const value = summaryData[config.column];
135	    row[config.column] = value;
136	    row[`${config.column}_pct`] =
137	      Number.isFinite(universeTotal) && universeTotal > 0 && Number.isFinite(value)
138	        ? value / universeTotal
139	        : NaN;
140	  });
