168	  const summaryStatConfig = summaryStatLabels.find(f => f.value === summaryType);
169	  const displayedStatLabels = summaryStatLabels.filter(f =>
170	    displayedColumnSets ? displayedColumnSets.includes(f.value) : true
171	  );
172	  const showSummaryTypeSelect = displayedStatLabels.length > 1;
173	  const showModeButtons = Boolean(
174	    summaryStatConfig?.supportedModes?.length && summaryStatConfig?.supportedModes?.length > 1
175	  );
176	  const numberFormat = numberFormats[evalMode];
177	  const isVoterHistory = summaryType === SUMMARY_TYPES.VOTERHISTORY;
178	  // Voter history columns are dem-share; Republican POV swaps to the rep-share columns.
179	  const effectiveColumnConfigs =
180	    isVoterHistory && pov === 'rep'
181	      ? columnConfigs.map(c => ({...c, column: c.column.replace('_dem', '_rep')}))
182	      : columnConfigs;
183	
184	  useEffect(() => {
185	    if (
186	      summaryStatConfig?.supportedModes?.length &&
187	      summaryStatConfig?.supportedModes?.length === 1
